import{_ as i,C as c,o as n,c as h,j as e,a as t,E as o,a5 as r}from"./chunks/framework.CyyS6Zdm.js";const w=JSON.parse('{"title":"热力图","description":"","frontmatter":{},"headers":[],"relativePath":"components/heatmap.md","filePath":"components/heatmap.md","lastUpdated":1787271946000}'),p={name:"components/heatmap.md"},s={id:"热力图",tabindex:"-1"};function u(m,d,b,g,x,f){const l=c("Badge"),a=c("XhDemo");return n(),h("div",null,[e("h1",s,[d[0]||(d[0]=t("热力图 ",-1)),o(l,{type:"info",text:"heatmap"}),d[1]||(d[1]=t()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#热力图","aria-label":'Permalink to "热力图 <Badge type="info" text="heatmap" />"'},"​",-1))]),d[3]||(d[3]=r('<p>按网格铺开的强度图：一格是一个观测点，颜色深浅表示它的数值落在第几档。三种形态共用同一套分档、色阶、图例与详情条，只是把格子摊开的方式不同——连续周列的一年日历、按自然月分块的月历、行列由作者给的矩阵。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>看一段连续日期上「哪几天多、哪几天少」，以及有没有成片的空档。</li><li>看逐月的分布，月与月之间要能对齐着比。</li><li>看两条离散坐标交叉出来的强度，比如「星期 × 小时」的活跃度、「品类 × 月份」的销量、相关系数矩阵。</li><li>强调节奏与分布，而不是某一格的准确数值。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>要挑日期、选区间：用<a href="./calendar">日历</a>，它才有选中语义与表单出口。</li><li>要读准确数字、要排序筛选：用<a href="./table">表格</a>。</li><li>只报一个总量或同比：用<a href="./statistic">统计数值</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>典型用法是一整年：<code>calendar</code> 形态给整年的起止日期，铺出 53 个周列 × 7 行、三百六十几格，一眼看完全年的节奏。下面各条里的取值都是按这个尺度定的。</li><li>三种形态由 <code>variant</code> 切换，不写即 <code>calendar</code>： <ul><li><code>calendar</code> 连续周列 × 星期行，月份名浮在网格上沿当坐标轴，适合看一整年的节奏；</li><li><code>month</code> 按自然月分块，每块是一张真月历，1 号落在它真实的星期几上，适合看逐月的分布——连续周列看不出月界，这是它存在的理由；</li><li><code>matrix</code> 行列都由作者用 <code>rows</code> / <code>columns</code> 给，数据按 <code>(row, column)</code> 定位，与日期无关。</li></ul></li><li>矩阵形态的格子两向分开量：宽走 <code>--xh-heatmap-column-w</code>、高走 <code>--xh-heatmap-row-h</code>，两者都不吃日历那把「一天一个小方块」的 <code>--xh-heatmap-cell-size</code>——那把尺是按「一年五十几列」定的，矩阵一行左边还挂着行名，格子照它定高就矮过行名，行高由行名的字定、格子在行里摊成一条。行高不写时是格宽尺的两倍（sm 16px / md 20px / lg 24px），每一档都高过行名那行字；列宽不写时取行高，一格缺省就是正方块。行高不接控件高度那把尺：那把尺是给可点可输的控件在一行里排齐用的，矩阵格子不可交互，接上去密度档一换矩阵就跟着变形。</li><li>数据收两种形状之一，按有没有 <code>date</code> 分辨：日期形态写 <code>{ date, count }</code>，矩阵形态写 <code>{ row, column, value }</code>。同一格出现多次即累加。</li><li>日期只认 ISO 的 <code>YYYY-MM-DD</code> 串，加减以 UTC 计，不引日期库。</li><li>区间起点不在周首日时会错列，两种日期形态的口径不同：<code>calendar</code> 是「排在起点星期几之前的那几行整行往后错一列」，<code>month</code> 是「本月首格错到 1 号真实的星期几」。两者都不铺没有日期的占位格。</li><li>月份名落在「这个月头一天所在的那一列」上：一列跨两个月时整列归后一个月。1 号极少正好是周首日，按「列里头一天所在的月」分段会让十二个月份名里有九个整体晚一列，读者顺着「2 月」往下看反而错过月初那几天。第 0 列是唯一的例外，它按区间首日所在的月归——起点落在月末（<code>2024-01-29</code> 起的近 365 天就是）时那一列只露出上个月末尾几天，跟着末一天走会让头一个月一个名字都不出。代价是这种区间里第二个月的名字排在第 1 列，比它 1 号所在的第 0 列晚一列。</li><li>一整年放不下一屏时网格自己横着滚，行首那一列星期名钉在起始缘不跟着走（矩阵形态的行名同理）。钉住的那一列自带 <code>--xh-bg-surface</code> 的底色，整块摆在别的底色上（卡片、分区）时要改写 <code>--xh-heatmap-bg</code>，否则那一列会是一块补丁。 月历形态例外：月块是换行排开的，宽度永远不超过容器，那一档不当滚动容器，也就没有钉住的那一列。</li><li>三张网格的推导都是纯函数（<code>buildHeatmapGrid</code> / <code>buildHeatmapMonthGrid</code> / <code>buildHeatmapMatrixGrid</code>），可以脱离组件单独调用来预生成数据。</li><li>格距四周一样宽：数据行的高度钉死成格子的边长，不由行首那一列星期名的字撑开。三档尺寸的横向与纵向格距都是「聚焦环偏移 + 环宽」那一个值（缺省 4px），格子 sm 8px / md 10px / lg 12px。</li><li>行首那一列星期名隔行画：只留第 0/2/4/6 行之外的那三行——周首日是星期一时是「二 / 四 / 六」，是星期日时是「一 / 三 / 五」。一行只有 10px 高而字是 12px，七个挨着写会上下叠在一起；隔一行之后每个留下来的字有两行的高度可用。三档尺寸一视同仁，不随档位变。要七行全画就把 <code>--xh-heatmap-week-day-skip</code> 改成一个看得见的颜色，比如 <code>var(--xh-heatmap-label-fg, var(--xh-fg-subtle))</code>（此时 <code>sm</code> 档会挨得很紧）。跳过的是字不是盒子：那几行只是字不上色，节点、文字、盒子与底色都还在——钉住那一列的实色底不能缺四行，缺了格子就从行首透出来，那四行也会不再参与命中测试，鼠标划过行首弹出的是看不见那一格的详情条。</li><li>色阶对照条两端各写一个字（缺省「少」「多」），一排色块自己说不出哪头是多。文案走 <code>translations.legendLow</code> / <code>legendHigh</code>，部件是 <code>legend-label</code>（<code>value</code> 写 <code>low</code> 或 <code>high</code>）；Vue 侧不写默认插槽时两端自动铺出来，WC 侧从元素的 <code>legendText</code> 属性取这两个字。</li><li>配色有两条路，缺省是品牌色。一条是 <code>tone</code> 语气轴（brand / neutral / success / warning / danger / info），与其余组件共用；另一条是 <code>palette</code> 色板轴（green / blue / orange / purple / red / gray），直接按颜色点名。色板只定色阶满档那一端的实心底，0 档的空格底与中间各档的兑法一概不动，也不参与语气层的悬停 / 淡底 / 前景派生——它是装饰性的一条轴，不是第四条语义轴。两个都写时听色板的：色板指名了一个具体颜色，语气只是推得出一个颜色。</li><li>档数可调：不给 <code>thresholds</code> 就按网格内的最大值均分，给了就以它为准。</li><li>要在图外报「总天数 / 空白天数与占比 / 最大值 / 平均值」不必自己再遍历一遍数据：三张网格都带 <code>max</code>（最大值）、<code>total</code>（总和）与 <code>emptyCount</code>（值为 0 的格子数），格子总数从 <code>cells.size</code> 读。<code>emptyCount</code> 数的是值为 0 的格子：没有数据的日子与写了 0 的日子都算。它不是「色阶第 0 档的格子数」——不给 <code>thresholds</code> 时首个下界恒为 1，两个数恰好相等；给了 <code>thresholds</code> 之后第 0 档还会收进低于首个下界的那些非零值，两个数不再相等。</li><li>悬停或键盘聚焦到某一格就显示详情条，内容由作者写；组件只给身份、位置与这一格的数据（日期或行列、原始值、档位、在色阶里的位置）。</li><li>语气与尺寸两轴与其余组件同源；色板轴是热力图独有的。</li><li>两个适配器的作者侧写法不同，最终 DOM 一致：Vue 侧不写默认插槽就按形态自动铺开整棵树，另有 <code>cell</code> 插槽往每格里塞内容（三种形态都铺，载荷是日历那一格或矩阵那一格，用 <code>&#39;date&#39; in cell</code> 分辨）、<code>tooltip</code> 插槽写详情条的内容（写了它才铺出详情条）；Web Components 侧元素不生成任何结构，各部件都要作者写进标记，元素只负责按部件名打属性。</li><li>Web Components 侧铺一整年不必手写三百多个格子：<code>&lt;xh-heatmap&gt;</code> 上有 <code>grid</code> / <code>monthGrid</code> / <code>matrixGrid</code> 三个只读属性，分别对应三种形态推导出来的网格（行、列、月份段、星期名、档位标尺都在里面），照着循环生成节点即可——元素一连上就读得到，接线排在这之后，当场铺出来的格子赶得上。每读一次都重算一遍整张网格，取一次存下来用。两个插槽是 Vue 专属，WC 侧靠 <code>cell-active</code> 事件自己填详情条。</li><li>自己写默认插槽铺网格时，锚点从载荷里的 <code>focusedCell</code> / <code>anchorCell</code> 读、用 <code>setFocusedCell</code> 挪：这一组三形态通用，带 <code>Date</code> 的那一组在矩阵形态下恒为 null。</li></ul><p>从别的库过来的对号入座表。左边一列是那些库写在 <code>color-theme</code> 上的取值，右边两列是本库的两条路——写哪一条都行，同一行的两种写法在缺省主题下产出同一个颜色（<code>gray</code> 是唯一的例外，见表下那条）：</p><table tabindex="0"><thead><tr><th>别处的 <code>color-theme</code></th><th>色板轴（推荐）</th><th>语气轴</th><th>满档实心底取的原语</th></tr></thead><tbody><tr><td><code>green</code></td><td><code>palette=&quot;green&quot;</code></td><td><code>tone=&quot;success&quot;</code></td><td><code>--xh-color-success-600</code></td></tr><tr><td><code>blue</code></td><td><code>palette=&quot;blue&quot;</code></td><td><code>tone=&quot;info&quot;</code></td><td><code>--xh-color-info-600</code></td></tr><tr><td><code>orange</code></td><td><code>palette=&quot;orange&quot;</code></td><td><code>tone=&quot;warning&quot;</code></td><td><code>--xh-color-warning-600</code></td></tr><tr><td><code>purple</code></td><td><code>palette=&quot;purple&quot;</code></td><td>语气轴里没有紫</td><td><code>--xh-color-purple-600</code></td></tr><tr><td><code>red</code></td><td><code>palette=&quot;red&quot;</code></td><td><code>tone=&quot;danger&quot;</code></td><td><code>--xh-color-danger-600</code></td></tr><tr><td>（多数库没有）</td><td><code>palette=&quot;gray&quot;</code></td><td><code>tone=&quot;neutral&quot;</code></td><td><code>--xh-color-neutral-600</code>；深色态换 <code>--xh-color-neutral-450</code></td></tr><tr><td>（多数库的缺省是绿）</td><td>不写</td><td>不写</td><td><code>--xh-bg-brand</code>，跟着使用者的品牌色走</td></tr></tbody></table><ul><li>灰是唯一按主题换档的一族：五个彩色族的 600 档明度在 0.577–0.705，深色态的空格底（<code>neutral-800</code>，明度 0.269）离得够远；中性 600 档只有 0.439，五档摊下来每档只差 0.0425、相邻两档对比度 1.16–1.20，等于看不出分档。因此深色态改取 <code>neutral-450</code>（明度 0.65），步长回到 0.095、相邻两档 1.42–1.50，与彩色族齐平；不取更亮的 <code>neutral-400</code> 是因为高对比档的 <code>border-default</code> 正是那一档，满档格子的描边会与底色同色。<code>tone=&quot;neutral&quot;</code> 没有这层照顾，要灰色热力图请写 <code>palette=&quot;gray&quot;</code>。</li><li>这七种之外的任何颜色一直都可以直接给：改写 <code>--xh-heatmap-ink</code>（满档的实心底）与 <code>--xh-heatmap-empty</code>（0 档的空格底），中间各档由这两端在 oklab 里兑出来。这个口子的优先级最高，色板与语气都压不过它。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一整年铺成周列 × 星期行的方格阵，颜色深浅表示当天数值落在第几档</p>',13)),o(a,{src:"heatmap/01-basic"}),d[4]||(d[4]=e("h3",{id:"语气换色",tabindex:"-1"},[t("语气换色 "),e("a",{class:"header-anchor",href:"#语气换色","aria-label":'Permalink to "语气换色"'},"​")],-1)),d[5]||(d[5]=e("p",null,"tone 决定用哪族颜色，色阶两端跟着换，格子的分档不变",-1)),o(a,{src:"heatmap/02-tone"}),d[6]||(d[6]=e("h3",{id:"色板换色",tabindex:"-1"},[t("色板换色 "),e("a",{class:"header-anchor",href:"#色板换色","aria-label":'Permalink to "色板换色"'},"​")],-1)),d[7]||(d[7]=e("p",null,"palette 直接按颜色点名，六个色板只换色阶满档那一端，分档与空格底都不动",-1)),o(a,{src:"heatmap/03-palette"}),d[8]||(d[8]=e("h3",{id:"尺寸",tabindex:"-1"},[t("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[9]||(d[9]=e("p",null,"size 换格子边长与行首星期名的留白，一屏能放下的周数跟着变",-1)),o(a,{src:"heatmap/04-size"}),d[10]||(d[10]=e("h3",{id:"档数",tabindex:"-1"},[t("档数 "),e("a",{class:"header-anchor",href:"#档数","aria-label":'Permalink to "档数"'},"​")],-1)),d[11]||(d[11]=e("p",null,"levels 决定分几档，图例与格子共用同一条色阶",-1)),o(a,{src:"heatmap/05-levels"}),d[12]||(d[12]=e("h3",{id:"焦点明细",tabindex:"-1"},[t("焦点明细 "),e("a",{class:"header-anchor",href:"#焦点明细","aria-label":'Permalink to "焦点明细"'},"​")],-1)),d[13]||(d[13]=e("p",null,"焦点落到某一天时报出日期与计数，键盘用户与鼠标用户看到同一份明细",-1)),o(a,{src:"heatmap/06-focus"}),d[14]||(d[14]=e("h3",{id:"月历形态",tabindex:"-1"},[t("月历形态 "),e("a",{class:"header-anchor",href:"#月历形态","aria-label":'Permalink to "月历形态"'},"​")],-1)),d[15]||(d[15]=e("p",null,"按自然月分块，每块是一张真月历，1 号落在它真实的星期几上",-1)),o(a,{src:"heatmap/07-month"}),d[16]||(d[16]=e("h3",{id:"矩阵形态",tabindex:"-1"},[t("矩阵形态 "),e("a",{class:"header-anchor",href:"#矩阵形态","aria-label":'Permalink to "矩阵形态"'},"​")],-1)),d[17]||(d[17]=e("p",null,"行列都由作者给，数据按行列定位而不按日期：星期 × 时段的活跃度",-1)),o(a,{src:"heatmap/08-matrix"}),d[18]||(d[18]=e("h3",{id:"悬停详情",tabindex:"-1"},[t("悬停详情 "),e("a",{class:"header-anchor",href:"#悬停详情","aria-label":'Permalink to "悬停详情"'},"​")],-1)),d[19]||(d[19]=e("p",null,"指针悬停与键盘聚焦走同一条路：详情条跟着那一格走，Escape 收起",-1)),o(a,{src:"heatmap/09-detail"}),d[20]||(d[20]=e("h3",{id:"年份切换",tabindex:"-1"},[t("年份切换 "),e("a",{class:"header-anchor",href:"#年份切换","aria-label":'Permalink to "年份切换"'},"​")],-1)),d[21]||(d[21]=e("p",null,"一排按钮换的是区间，网格、月份段、色阶与锚点全按新区间从头算",-1)),o(a,{src:"heatmap/10-year"}),d[22]||(d[22]=e("h3",{id:"数据统计",tabindex:"-1"},[t("数据统计 "),e("a",{class:"header-anchor",href:"#数据统计","aria-label":'Permalink to "数据统计"'},"​")],-1)),d[23]||(d[23]=e("p",null,"总天数、空白天数与占比、最大值、平均值都从网格模型直接读，不必自己再遍历一遍数据",-1)),o(a,{src:"heatmap/11-stats"}),d[24]||(d[24]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-heatmap&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhHeatmapCell</code> <code>XhHeatmapColumnLabel</code> <code>XhHeatmapGrid</code> <code>XhHeatmapLegend</code> <code>XhHeatmapLegendItem</code> <code>XhHeatmapLegendLabel</code> <code>XhHeatmapMonthBlock</code> <code>XhHeatmapMonthLabel</code> <code>XhHeatmapRoot</code> <code>XhHeatmapRow</code> <code>XhHeatmapRowLabel</code> <code>XhHeatmapTooltip</code> <code>XhHeatmapWeekDayLabel</code></td></tr><tr><td>组合式函数</td><td><code>useHeatmap</code></td></tr><tr><td>状态机</td><td><code>heatmapMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/heatmap.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;heatmap&quot;</code>：<strong><code>root</code></strong> · <strong><code>grid</code></strong> · <code>month-block</code> · <code>row</code> · <code>week-day-label</code> · <code>month-label</code> · <code>row-label</code> · <code>column-label</code> · <code>cell</code> · <code>tooltip</code> · <code>legend</code> · <code>legend-label</code> · <code>legend-item</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>variant</code></td><td><code>HeatmapVariant</code></td><td></td><td>形态：calendar 连续周列、month 按自然月分块、matrix 行列由作者给；缺省 calendar。</td></tr><tr><td><code>value</code></td><td><code>HeatmapValue[]</code></td><td></td><td>数据。日期形态收 { date, count }，矩阵形态收 { row, column, value }；同一格出现多次即累加。</td></tr><tr><td><code>rows</code></td><td><code>HeatmapAxisInput[]</code></td><td></td><td>矩阵的行，顺序即渲染顺序；只写身份或身份与文本分开写都行。</td></tr><tr><td><code>columns</code></td><td><code>HeatmapAxisInput[]</code></td><td></td><td>矩阵的列，顺序即渲染顺序。</td></tr><tr><td><code>startDate</code></td><td><code>string</code></td><td></td><td>区间起点（含），ISO YYYY-MM-DD。缺省或非法即空网格。</td></tr><tr><td><code>endDate</code></td><td><code>string</code></td><td></td><td>区间终点（含）。早于起点即空网格。</td></tr><tr><td><code>levels</code></td><td><code>number</code></td><td></td><td>档数，缺省 5；给了 thresholds 则档数由它定。</td></tr><tr><td><code>thresholds</code></td><td><code>number[]</code></td><td></td><td>各档的下界，升序；给了它 levels 不再起作用。</td></tr><tr><td><code>firstDayOfWeek</code></td><td><code>number</code></td><td></td><td>周首日，0 = 星期日，缺省 1。</td></tr><tr><td><code>locale</code></td><td><code>string</code></td><td></td><td>月份名与星期名的书写 locale，缺省 zh-CN。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向。只作显式覆盖：不写时方向从 DOM 现读， 左右方向键的语义跟着视觉次序走，上下键与它无关。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>palette</code></td><td><code>HeatmapPalette</code></td><td></td><td>色板：green / blue / orange / purple / red / gray，直接点名色阶满档那一端的颜色；同时写了 tone 时听它的。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;HeatmapTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onCellFocus</code></td><td><code>(details: HeatmapCellFocusDetails) =&gt; void</code></td><td></td><td>DOM 焦点落到某一格时通知一次；同一格重复聚焦不重复通知。 只由真实的聚焦触发，程序化挪锚点（<code>setFocusedCell</code>）不派这个回调。</td></tr><tr><td><code>onCellActive</code></td><td><code>(details: HeatmapCellDetails | null) =&gt; void</code></td><td></td><td>详情该显示哪一格：指针悬停或键盘聚焦都会走到这里，收起时给 null。 详情条里写什么由作者决定，组件只报是哪一格、数值多少。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>cell-focus</code></td><td><code>HeatmapCellFocusDetails</code></td><td>焦点落到某一格；detail 为 <code>{ date, row, column, count, level, percent }</code></td></tr><tr><td><code>cell-active</code></td><td><code>HeatmapCellDetails</code></td><td>详情该显示哪一格（悬停或聚焦）；收起时 detail 为 null</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhHeatmapRoot</code></td><td><code>default</code></td><td><code>HeatmapRootSlotProps</code></td><td></td></tr><tr><td><code>XhHeatmapRoot</code></td><td><code>cell</code></td><td><code>HeatmapCellSlotProps</code></td><td>铺开网格时每一格的内容插槽，缺省是空格子；三种形态都铺。</td></tr><tr><td><code>XhHeatmapRoot</code></td><td><code>tooltip</code></td><td><code>HeatmapCellDetails | null</code></td><td>详情条的内容插槽；写了它才会铺出 tooltip 部件。</td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>CELL.FOCUS</code> · <code>CELL.BLUR</code> · <code>CELL.ENTER</code> · <code>CELL.LEAVE</code> · <code>DETAIL.DISMISS</code> · <code>FOCUS.SET</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useHeatmap</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>variant</code></td><td><code>HeatmapVariant</code></td><td>当前形态。</td></tr><tr><td><code>grid</code></td><td><code>HeatmapGrid</code></td><td>日历网格：行是星期几、列是周次，另带月份段、星期名与档位标尺。其余形态下是一张空网格。</td></tr><tr><td><code>monthGrid</code></td><td><code>HeatmapMonthGrid | null</code></td><td>月历网格：按自然月分块；不是 month 形态时为 null。</td></tr><tr><td><code>matrixGrid</code></td><td><code>HeatmapMatrixGrid | null</code></td><td>矩阵网格：行列由作者给；不是 matrix 形态时为 null。</td></tr><tr><td><code>focusedCell</code></td><td><code>HeatmapCellRef | null</code></td><td>最后一次被聚焦的那一格；从没聚焦过时为 null。</td></tr><tr><td><code>focusedDate</code></td><td><code>string | null</code></td><td>最后一次被聚焦的那一天；矩阵形态下恒为 null。</td></tr><tr><td><code>anchorCell</code></td><td><code>HeatmapCellRef | null</code></td><td>当下占着 Tab 位的那一格：锚点还在网格里就是它，否则退回文档序头一格。</td></tr><tr><td><code>anchorDate</code></td><td><code>string | null</code></td><td>当下占着 Tab 位的那一天；矩阵形态下恒为 null。</td></tr><tr><td><code>activeCell</code></td><td><code>HeatmapCellDetails | null</code></td><td>详情该显示哪一格的数据：身份、原始值、档位与色阶位置；不显示时为 null。</td></tr><tr><td><code>detailOpen</code></td><td><code>boolean</code></td><td>详情条此刻是不是显示着。</td></tr><tr><td><code>legendText</code></td><td><code>{ low: string, high: string }</code></td><td>对照条两端要写的那两个字，作者照它渲染 legend-label 部件。 与 <code>getLegendLabelProps</code> 同源，改 translations 两处一起变。</td></tr><tr><td><code>cellAt</code></td><td><code>(date: string) =&gt; HeatmapCellMeta | null</code></td><td>按日期取一格；不在区间内给 null。矩阵形态下恒为 null。</td></tr><tr><td><code>setFocusedCell</code></td><td><code>(cell: HeatmapCellRef | null) =&gt; void</code></td><td>挪动锚点。只改锚点不搬 DOM 焦点，也不派 <code>onCellFocus</code>； 需要焦点跟着走的自行调用元素的 focus()。</td></tr><tr><td><code>setFocusedDate</code></td><td><code>(date: string | null) =&gt; void</code></td><td>按日期挪动锚点，等同于 <code>setFocusedCell({ date })</code>。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGridProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMonthBlockProps</code></td><td><code>(props: HeatmapMonthBlockProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getRowProps</code></td><td><code>(props: HeatmapRowProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getWeekDayLabelProps</code></td><td><code>(props: HeatmapWeekDayLabelProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMonthLabelProps</code></td><td><code>(props: HeatmapMonthLabelProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getRowLabelProps</code></td><td><code>(props: HeatmapRowLabelProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getColumnLabelProps</code></td><td><code>(props: HeatmapColumnLabelProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCellProps</code></td><td><code>(props: HeatmapCellProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendLabelProps</code></td><td><code>(props: HeatmapLegendLabelProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendItemProps</code></td><td><code>(props: HeatmapLegendItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/grid/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>总是</td><td>整张网格只占一个 Tab 位：焦点落到锚点那一格，一格都没有时落网格自己</td></tr><tr><td><code>ArrowLeft</code></td><td>focus in grid</td><td>焦点横着退一格：日历形态是上一周的同一天，月历形态是前一天（跨得过月块），矩阵形态是左边一列；已在头一格则原地不动。dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>ArrowRight</code></td><td>focus in grid</td><td>焦点横着进一格：日历形态是下一周的同一天，月历形态是后一天（跨得过月块），矩阵形态是右边一列；已在末一格则原地不动。dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowUp</code></td><td>focus in grid</td><td>焦点竖着退一格：日历形态是前一天，月历形态是上一周的同一天，矩阵形态是上面一行；走出网格则原地不动</td></tr><tr><td><code>ArrowDown</code></td><td>focus in grid</td><td>焦点竖着进一格：日历形态是后一天，月历形态是下一周的同一天，矩阵形态是下面一行；走出网格则原地不动</td></tr><tr><td><code>Home</code></td><td>focus in grid</td><td>焦点移到本行头一格：日历形态是这个星期几最早的一天，月历形态是这一周在本月里的头一天，矩阵形态是头一列</td></tr><tr><td><code>End</code></td><td>focus in grid</td><td>焦点移到本行末一格：日历形态是这个星期几最晚的一天，月历形态是这一周在本月里的末一天，矩阵形态是末一列</td></tr><tr><td><code>Ctrl+Home</code></td><td>focus in grid</td><td>焦点移到整张网格文档序的头一格</td></tr><tr><td><code>Ctrl+End</code></td><td>focus in grid</td><td>焦点移到整张网格文档序的末一格</td></tr><tr><td><code>Escape</code></td><td>详情条显示着</td><td>收起详情条；焦点留在原处，按键不拦截（外层浮层的关闭仍归它自己管）</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>grid</code></td><td><code>aria-colcount</code></td><td>counts.columns | undefined</td></tr><tr><td><code>grid</code></td><td><code>aria-label</code></td><td>translations?.gridLabel</td></tr><tr><td><code>grid</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39;</td></tr><tr><td><code>grid</code></td><td><code>aria-rowcount</code></td><td>counts.rows | undefined</td></tr><tr><td><code>grid</code></td><td><code>role</code></td><td>&#39;grid&#39;</td></tr><tr><td><code>month-block</code></td><td><code>aria-label</code></td><td>monthBlockOf.get(block.value)?.long</td></tr><tr><td><code>month-block</code></td><td><code>role</code></td><td>&#39;rowgroup&#39;</td></tr><tr><td><code>row</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>row</code></td><td><code>aria-label</code></td><td>undefined | grid.weekDays[row.weekDay]?.long</td></tr><tr><td><code>row</code></td><td><code>aria-rowindex</code></td><td>1</td></tr><tr><td><code>row</code></td><td><code>role</code></td><td>&#39;row&#39;</td></tr><tr><td><code>week-day-label</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>month-label</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>row-label</code></td><td><code>aria-colindex</code></td><td>1</td></tr><tr><td><code>row-label</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>row-label</code></td><td><code>role</code></td><td>&#39;rowheader&#39;</td></tr><tr><td><code>column-label</code></td><td><code>aria-colindex</code></td><td>meta.index + 2 | undefined</td></tr><tr><td><code>column-label</code></td><td><code>role</code></td><td>&#39;columnheader&#39;</td></tr><tr><td><code>cell</code></td><td><code>aria-colindex</code></td><td>meta.columnIndex + 2 | undefined</td></tr><tr><td><code>cell</code></td><td><code>aria-label</code></td><td>matrixCellLabel({ date: &#39;&#39;, row, column, count, level…</td></tr><tr><td><code>cell</code></td><td><code>role</code></td><td>&#39;gridcell&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>legend</code></td><td><code>aria-label</code></td><td>translations?.legendLabel</td></tr><tr><td><code>legend</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>网格是 <code>role=&quot;grid&quot;</code> 且 <code>aria-readonly</code>，每行一个 <code>role=&quot;row&quot;</code>，每格一个 <code>role=&quot;gridcell&quot;</code>。</li><li>月历形态里一个自然月是一个 <code>role=&quot;rowgroup&quot;</code>，块的可及名字是这个月的长名字；块里那条星期名坐标轴整条 <code>aria-hidden</code>，读屏看到的每一块就只剩合法的几行。</li><li>矩阵形态里行名是 <code>role=&quot;rowheader&quot;</code>、列名是 <code>role=&quot;columnheader&quot;</code>，表头行行首那个角落占位 <code>aria-hidden</code>；行列总数把两条表头也算进去，读屏报的行列号才对得上。</li><li>格子里没有文字，可及名字全靠文案拼出来：日期形态走 <code>translations.cellLabel</code>（日期 + 数值），矩阵形态走 <code>translations.matrixCellLabel</code>（行 + 列 + 数值），务必按本地语言改写它们。</li><li>星期名、月份名与图例里的色块都是给眼睛看的坐标轴，一律 <code>aria-hidden</code>：每格自己就念得出完整身份与数值，再念一遍轴只是噪音。</li><li>日历形态里星期名是隔行画的，肉眼靠上下文补得出被跳过的那几行：因此每一行自带 <code>aria-label</code>，写的是这一行星期几的全称（<code>星期一</code> 这种）。这个名字跟 <code>locale</code> 走、不进 <code>translations</code>——它念的就是坐标轴上那个词，两处必须逐字一致（月块的名字同理）。它只是一层补充：<code>role=&quot;row&quot;</code> 上的名字并非所有读屏在方向键导航时都播报，而每一格的可及名字里本就带完整日期，星期几这条信息从来没丢过。</li><li>图例整体是 <code>role=&quot;group&quot;</code>，名字走 <code>translations.legendLabel</code>：一排色块自己说不出这是干什么用的。两端那两个字是真文字、不藏，色阶朝哪个方向深因此说得出口——深色代表多还是少是约定俗成而非自明的。</li><li>详情条 <code>aria-hidden</code>：它显示的信息与那一格的可及名字是同一份，念两遍反而吵。<strong>因此详情条里不能出现可及名字里没有的内容</strong>，否则读屏用户就少了一块。</li><li>各行格子数不一定齐（首行可能少一格），格子上带 <code>aria-colindex</code>，读屏报出的列号才对得上。</li><li>整张网格只占一个 Tab 位，进去以后靠方向键走。键盘聚焦与指针悬停触发的是同一条详情：只做悬停等于把键盘与读屏用户排除在外。</li><li>Escape 收起详情条但不拦截按键：外层浮层的关闭仍归它自己管。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/heatmap.css</code> 按部件选择：<code>[data-scope=&quot;heatmap&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-palette</code></td><td>props.palette</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>row</code></td><td><code>data-week</code></td><td>String(row.week)</td></tr><tr><td><code>row</code></td><td><code>data-week-day</code></td><td>undefined | String(row.weekDay)</td></tr><tr><td><code>week-day-label</code></td><td><code>data-week-day</code></td><td>undefined | String(label.weekDay)</td></tr><tr><td><code>cell</code></td><td><code>data-level</code></td><td>String(level)</td></tr><tr><td><code>tooltip</code></td><td><code>data-inline-anchor</code></td><td>undefined | tip.inlineAnchor</td></tr><tr><td><code>tooltip</code></td><td><code>data-placement</code></td><td>undefined | ((): &#39;block-start&#39; | &#39;block-end&#39; =&gt; { if (activeRef =…</td></tr><tr><td><code>legend-label</code></td><td><code>data-bound</code></td><td>label.bound</td></tr><tr><td><code>legend-item</code></td><td><code>data-level</code></td><td>String(item.level)</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-heatmap-bg</code> · <code>--xh-heatmap-block-gap</code> · <code>--xh-heatmap-block-inner-gap</code> · <code>--xh-heatmap-cell-border</code> · <code>--xh-heatmap-cell-radius</code> · <code>--xh-heatmap-cell-size</code> · <code>--xh-heatmap-column-w</code> · <code>--xh-heatmap-empty</code> · <code>--xh-heatmap-fg</code> · <code>--xh-heatmap-font-size</code> · <code>--xh-heatmap-gap</code> · <code>--xh-heatmap-grid-gap</code> · <code>--xh-heatmap-gutter</code> · <code>--xh-heatmap-ink</code> · <code>--xh-heatmap-label-fg</code> · <code>--xh-heatmap-legend-gap</code> · <code>--xh-heatmap-py</code> · <code>--xh-heatmap-row-gap</code> · <code>--xh-heatmap-row-h</code> · <code>--xh-heatmap-sticky-z</code> · <code>--xh-heatmap-title-fg</code> · <code>--xh-heatmap-tooltip-bg</code> · <code>--xh-heatmap-tooltip-fg</code> · <code>--xh-heatmap-tooltip-font-size</code> · <code>--xh-heatmap-tooltip-max-w</code> · <code>--xh-heatmap-tooltip-px</code> · <code>--xh-heatmap-tooltip-py</code> · <code>--xh-heatmap-tooltip-radius</code> · <code>--xh-heatmap-tooltip-shadow</code> · <code>--xh-heatmap-tooltip-z</code> · <code>--xh-heatmap-week-day-skip</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>横轴沿 inline 排开，整页切成 rtl 时视觉次序整体翻转，左右方向键的语义跟着翻，上下键不受影响。</li><li>方向从 DOM 现读，祖先链上任意一处 <code>dir</code> 或 CSS <code>direction</code> 都算数；<code>dir</code> 属性只作显式覆盖。</li><li>详情条的落点也按逻辑方向量：rtl 下从末缘往回量，样式侧只写一条 <code>inset-inline-start</code> 就两向通用。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>详情条不引浮层引擎，也就不参与浮层的层级与关闭协议：它按 root 的内边距盒绝对定位，跟着网格一起横向滚动，摆上边还是摆下边按格子的行序定，因此始终压在网格自己身上。条比一格宽得多，格子末缘之前的地方比起始缘之后多时它就改从末缘往回长，不越过滚动容器的末缘——否则整年铺开时后三分之一的格子悬停出来的条会被裁掉，横向滚动条还会跟着一伸一缩。挑的是两侧空间大的那一边，与条自己多宽无关（条的宽在量落点那一刻还拿不到：内容马上要换，收起时又是 <code>display:none</code>）；容器窄到条比大的那一侧还宽时，条仍会被裁掉一截，两侧都摆不下是没有解的。要一条会翻转、会避让视口的真浮层，请自己在格子上挂<a href="./tooltip">提示</a>。</li><li>与<a href="./calendar">日历</a>并排：一个看分布、一个挑日期。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>图例两端的那两个字照默认铺出来就好；要换成「Less / More」或别的说法改 <code>translations.legendLow</code> / <code>legendHigh</code>，别把它们删掉——只给一排色块，读者猜不出深色是多还是少。</li><li>深浅不是唯一线索：数值必须在文案里说清楚，否则色觉障碍的用户什么都读不到。</li><li>一张图只挑一条轴：要表达「这一族数据是告警」就写 <code>tone</code>，要表达「这张图用绿色」就写 <code>palette</code>，两个都写只会让读代码的人猜哪个赢。同一页并排的几张图更要统一，混着写会让读者以为颜色有语义。</li><li>色板换的只是颜色不是语义：<code>palette=&quot;red&quot;</code> 的格子不代表这些天出了问题，那层意思只能靠标题与文案说。</li><li>数据里出现极端值时自己给 <code>thresholds</code>，按最大值均分会把其余格子全压到第 0、1 档，整张图变成一片空白加一个亮点。</li><li>一屏放不下就让网格自己横向滚动，不要把格子压到看不清。整年在 <code>md</code> 档要 774px 上下，<code>sm</code> 档 660px 上下，容器窄于这个数就会出横向滚动条。</li><li>键盘走到视口外的格子时网格会自己滚过去，落点已经让开钉住的那一列；给 root 另加内边距或换 <code>--xh-heatmap-gutter</code> 时不必再管这件事，两处读的是同一个值。</li><li>矩阵的列名与它下面那一列的格子同宽：标签长就整体调大 <code>--xh-heatmap-column-w</code>，别只把标签撑开——撑开的标签会与格子错位。</li><li>调宽了列就一并调高行：只给 <code>--xh-heatmap-column-w</code> 而不给 <code>--xh-heatmap-row-h</code>，格子会横着拉成细条。两个值配到 1.5 : 1 上下最好读，一屏放不下就减列不要压扁行。</li><li>矩阵的行列顺序就是渲染顺序，按你希望读者阅读的次序给，别指望组件替你排。</li><li>月历形态里上下键走的是「上一周 / 下一周同一天」，跨得过月块：从一月块最后一行按 ↓ 会落到二月块里，而月块是并排换行的，视觉上像往右上方跳了一下。要按块阅读就用左右键，它逐日走、次序与肉眼一致。矩阵形态没有这回事，它的行列是无序的类目，上下键到边即停。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>拿它当日期选择器：格子不可点、没有选中语义，点开一个浮层去改值属于另一件事。</li><li>一次铺好几年：列数上千以后既看不出节奏，键盘也走不到头。</li><li>只用颜色不给文案：一张没有可及名字的方格阵，对读屏用户等于一片空白。</li><li>把详情条当唯一的信息出口：它对读屏是藏起来的，只写在那里等于只给鼠标用户看。</li><li>矩阵形态里指望组件从数据里猜出行列：轴上没有的行列，数据里写了也不进网格。</li></ul>',47))])}const P=i(p,[["render",u]]);export{w as __pageData,P as default};
